const adminOnly=['edit-profile','avatar','new-tx','edit-tx','delete-tx','attach','add-file','delete-file','pin-file','backup','restore','new-card','jar-delete','delete-regular'];
for(const [name,fn] of Object.entries(actions)){if(name.startsWith('admin-')||adminOnly.includes(name))actions[name]=(...args)=>{if(!adminMode){toast('Редагування доступне в окремій адмінці проєкту');return}return fn(...args)}}
const baseRender=render;
render=function(){defaults();if(adminMode&&!['file','receipt','detail'].includes(route.page)){
$('#app').className='admin';$('#nav').hidden=true;$('#screen').innerHTML=loading?empty('Завантаження…',''):adminPage();if($('#admin-search'))$('#admin-search').oninput=e=>$('#admin-tx-list').innerHTML=adminTxRows(e.target.value);
}else{baseRender();if(adminMode){$('#app').classList.add('admin-inspect');$('#nav').hidden=true}if(route.page==='card')$('#nav').hidden=true;const c=activeCard();$('#app').classList.toggle('white-active',(c.color?c.color==='white':c.id==='white'));if(!adminMode&&route.page==='home')bindCardSwipe();}
};
function bindCardSwipe(){const stage=$('#card-swipe');if(!stage)return;let start;stage.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY}});stage.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.5){e.preventDefault();const cards=allCards(),idx=cards.findIndex(c=>c.id===activeCard().id),next=(idx+(dx<0?1:-1)+cards.length)%cards.length;change(()=>state.activeCard=cards[next].id);stage.addEventListener('click',e=>{e.preventDefault();e.stopPropagation()},{once:true,capture:true})}});stage.addEventListener('pointercancel',()=>start=null)}
let cardTransition;
function measureCardPose(el){const rect=el.getBoundingClientRect(),slide=el.classList.contains('card-face')?el.closest('.card-slide'):null,anchor=slide?slide.getBoundingClientRect():rect;
 const rear=route.page==='home'&&el.matches('.expanded-card')&&Number(getComputedStyle(el.querySelector('.bank-card-back')).opacity)>.5;
 return {rect,width:el.offsetWidth,center:{x:anchor.x+anchor.width/2,y:anchor.y+anchor.height/2},scale:el.classList.contains('card-face')?1:rect.width/el.offsetWidth,flipped:el.classList.contains('flipped'),glint:el.querySelector('.card-glint')?{opacity:getComputedStyle(el.querySelector('.card-glint')).opacity,transform:getComputedStyle(el.querySelector('.card-glint')).transform}:null,shadow:el.querySelector('.bank-card')?getComputedStyle(el.querySelector('.bank-card')).boxShadow:'none',surface:el.querySelector('.bank-card-front')?getComputedStyle(el.querySelector('.bank-card-front')).background:null,snapshot:!rear&&typeof captureBankSurface==='function'?captureBankSurface():null}}
function expandTransition(from,to,opening){
 if(!from||!to||shouldReduceMotion())return;
 cardTransition?.finish();
 const destination=to.getBoundingClientRect(),width=opening?to.offsetWidth:from.width,height=width/1.586,flat=opening?destination:{x:from.center.x-width/2,y:from.center.y-height/2},duration=opening?520:480;
 const slide=to.classList.contains('card-face')?to.closest('.card-slide')?.getBoundingClientRect():null;
 const homeCenter=opening?from.center:{x:(slide||destination).x+(slide||destination).width/2,y:(slide||destination).y+(slide||destination).height/2};
 const dx=homeCenter.x-flat.x-width/2,dy=homeCenter.y-flat.y-height/2,ratio=(opening?from.width:to.offsetWidth)/width;
 const node=document.createElement('div');node.className='card-transition';node.innerHTML=cardArtwork(activeCard());
 Object.assign(node.style,{position:'fixed',left:flat.x+'px',top:flat.y+'px',width:width+'px',height:height+'px',zIndex:40,pointerEvents:'none'});
 const backdrop=from.snapshot;if(backdrop){document.body.append(backdrop);backdrop.animate([{opacity:1,offset:0},{opacity:1,offset:.4},{opacity:0,offset:1}],{duration,easing:'ease-out'}).finished.catch(()=>{}).finally(()=>backdrop.remove())}
 document.body.append(node);
 const front=node.querySelector('.bank-card-front'),destinationFront=to.querySelector('.bank-card-front');
 const glint=node.querySelector('.card-glint'),targetGlint=to.querySelector('.card-glint');if(glint&&targetGlint&&from.glint){const target={opacity:getComputedStyle(targetGlint).opacity,transform:getComputedStyle(targetGlint).transform};glint.animate([from.glint,target],{duration,easing:'cubic-bezier(.32,.72,0,1)',fill:'both'})}
 if(front){const shade=document.createElement('span');shade.className='card-transition-shade';shade.style.background=opening?from.surface:getComputedStyle(destinationFront).background;front.prepend(shade);shade.animate(opening?[{opacity:1},{opacity:0}]:[{opacity:0},{opacity:1}],{duration,easing:'ease-out',fill:'forwards'})}
 const brand=node.querySelector('.card-brand');const homeBrand='translate3d('+width*.017+'px,'+(-height*.02)+'px,0) scale(.823529)',flatBrand='translate3d(0px,0px,0px) scale(1)';if(brand){brand.style.transformOrigin='left top';brand.animate(opening?[{transform:homeBrand},{transform:flatBrand}]:[{transform:flatBrand},{transform:homeBrand}],{duration,easing:'cubic-bezier(.32,.72,0,1)',fill:'forwards'})}
 const number=node.querySelector('.card-printed-number'),sourceNumber=(opening?document.querySelector('.card-face[data-id="'+state.activeCard+'"]'):to)?.querySelector('.card-printed-number');if(number){const full=number.querySelector('.card-number-full'),masked=number.querySelector('.card-number-masked');if(full&&masked){full.style.display=masked.style.display='inline';Object.assign(full.style,{position:'absolute',left:'0',top:'0'});full.animate(opening?[{opacity:0},{opacity:1}]:[{opacity:1},{opacity:0}],{duration,easing:'ease-out',fill:'both'});masked.animate(opening?[{opacity:1},{opacity:0}]:[{opacity:0},{opacity:1}],{duration,easing:'ease-out',fill:'both'})}const homeFont=(sourceNumber?parseFloat(getComputedStyle(sourceNumber).fontSize):17)/ratio,fullFont=parseFloat(getComputedStyle(number).fontSize);number.style.transformOrigin='left center';number.animate(opening?[{transform:`scale(${homeFont/fullFont})`},{transform:'scale(1)'}]:[{transform:'scale(1)'},{transform:`scale(${homeFont/fullFont})`}],{duration,easing:'cubic-bezier(.32,.72,0,1)',fill:'both'})}node.querySelector('.card-holder')?.animate(opening?[{opacity:0},{opacity:1}]:[{opacity:1},{opacity:0}],{duration,easing:'ease-out',fill:'both'});
 const art=node.querySelector('.bank-card'),destinationArt=to.querySelector('.bank-card'),scaleShadow=(shadow,factor)=>shadow.replace(/(-?[\d.]+)px/g,(_,n)=>(Number(n)/factor)+'px');const homeShadow=opening?scaleShadow(from.shadow,ratio):scaleShadow(getComputedStyle(destinationArt).boxShadow,ratio),fullShadow=opening?getComputedStyle(destinationArt).boxShadow:from.shadow;art.animate(opening?[{boxShadow:homeShadow},{boxShadow:fullShadow}]:[{boxShadow:fullShadow},{boxShadow:homeShadow}],{duration,easing:'ease-out',fill:'both'});if(!opening&&from.flipped)art.animate([{transform:'rotateY(180deg)'},{transform:'rotateY(0deg)'}],{duration,easing:'cubic-bezier(.77,0,.175,1)',fill:'both'});
 to.style.opacity='0';
 if(opening)document.querySelectorAll('.card-settings>.payment-settings,.card-settings>h2,.card-settings>.settings-group,.card-close').forEach(el=>el.animate([{opacity:0},{opacity:1}],{duration:Math.round(duration*.4),delay:Math.round(duration*.6),easing:'ease-out',fill:'backwards'}));
 const home=`translate3d(${dx}px,${dy}px,0px) perspective(900px) rotateX(65deg) scale(${ratio})`,expanded=`translate3d(0px,0px,0px) perspective(900px) rotateX(0deg) scale(${opening?1:from.scale||1})`;
 cardTransition=node.animate(opening?[{transform:home},{transform:expanded}]:[{transform:expanded},{transform:home}],{duration,easing:'cubic-bezier(.32,.72,0,1)'});
 cardTransition.finished.catch(()=>{}).finally(()=>{node.remove();to.style.opacity=''});
}

const baseNavigate=navigate;
navigate=function(page,id){const el=route.page==='home'&&page==='card'?$('.card-face[data-id="'+state.activeCard+'"]')||$('.card-face'):null,from=el?measureCardPose(el):null;cardFlipped=false;baseNavigate(page,id);if(from)expandTransition(from,$('.expanded-card'),true)};
